#pragma once
#include "../Runtime/ComputerUseDesktopLease.h"
#include "../Runtime/ComputerUseProcess.h"
#include <filesystem>
#include <fstream>

namespace coincide {
// Kernel mutex/mapping and dedicated fake helper only. Scope::for_window is never called:
// these fixtures do not enumerate desktops/windows, query UIA, capture pixels or send input.
inline int computer_use_desktop_lease_tests(const std::filesystem::path& report,const std::filesystem::path& fixture){
    using namespace computer_use;int checks{};auto check=[&](bool condition,const char* message){++checks;if(!condition)throw std::runtime_error(message);};auto rejects=[&](auto operation,const char* message){bool failed{};try{operation();}catch(...){failed=true;}check(failed,message);};
    const auto root=std::filesystem::temp_directory_path()/(L"Coincide-CU-lease-fixture-"+std::to_wstring(GetCurrentProcessId())+L"-"+std::to_wstring(GetTickCount64()));struct Cleanup{std::filesystem::path value;~Cleanup(){std::error_code ignored;std::filesystem::remove_all(value,ignored);}}cleanup{root};
    const std::string a="{65e2f1d1-cc61-40b5-95bd-d29c345c444c}",b="{05bd2cb4-5b1b-4dba-9a2c-89d9ea45801c}";
    try{
        if(!fixture.is_absolute()||fixture.filename()!=L"CoincideComputerUseFixture.exe"||!std::filesystem::is_regular_file(fixture))throw std::invalid_argument("Pass the exact dedicated Computer Use fixture executable");std::filesystem::create_directories(root);
        const auto scope=DesktopLease::Scope::fixture("lifecycle-"+random_id());std::uint64_t clock=1000;DesktopLease first(scope,[&]{return clock;}),second(scope,[&]{return clock;});
        rejects([&]{first.try_acquire("../other");},"A desktop lease must require a canonical conversation identity");rejects([&]{first.try_acquire(a,0);},"Zero-length leases must be rejected");rejects([&]{first.try_acquire(a,60001);},"A lease may not exceed the bounded native input interval");
        auto guard=first.try_acquire(a);check(guard.has_value()&&first.owns(a),"A fresh user/desktop scope must acquire its own input gate and thread lease");
        check(!second.try_acquire(b)&&!first.try_acquire(a),"An active input gate must reject competing or recursive actions");clock+=60001;check(!second.try_acquire(b),"An in-progress input gate cannot be stolen merely because its idle lease elapsed");guard.reset();
        auto replacement=second.try_acquire(b);check(replacement.has_value(),"An expired idle lease may pass to a new owner after its action releases the mutex");replacement.reset();check(!first.try_acquire(a)&&second.owns(b),"A live unexpired owner in the same process must still exclude another controller object");
        check(!first.release(b)&&!second.release(a)&&second.owns(b),"A foreign controller or conversation must not release another owner's desktop lease");check(second.release(b)&&!second.owns(b),"Explicit release must clear only its matching idle owner");
        guard=first.try_acquire(a);check(guard.has_value(),"A released desktop must be immediately available to another owner");guard.reset();check(first.release(a),"The new owner must be able to release its own scope");
        const auto other_scope=DesktopLease::Scope::fixture("other-"+random_id());DesktopLease other(other_scope,[&]{return clock;});guard=first.try_acquire(a);auto unrelated=other.try_acquire(b);check(unrelated.has_value(),"Independent synthetic desktop namespaces must not reserve the real or another fixture desktop");unrelated.reset();guard.reset();first.release(a);
        {auto temporary=std::make_unique<DesktopLease>(scope,[&]{return clock;});auto value=temporary->try_acquire(a);check(value.has_value(),"A temporary lease owner must acquire normally");value.reset();temporary.reset();check(second.try_acquire(b).has_value(),"Destroying an idle owner must not strand a same-process lease until expiry");second.release(b);}
        {auto temporary=std::make_unique<DesktopLease>(scope,[&]{return clock;});auto value=temporary->try_acquire(a);temporary.reset();check(!second.try_acquire(b),"A guard must retain its kernel state safely after its lease object is destroyed");value.reset();auto next=second.try_acquire(b);check(next.has_value(),"The last guard must release a closed owner's logical lease and mutex together");next.reset();second.release(b);}
        const auto insecure=DesktopLease::Scope::fixture("insecure-"+random_id());PSECURITY_DESCRIPTOR descriptor{};if(!ConvertStringSecurityDescriptorToSecurityDescriptorW(L"D:P(A;;GA;;;WD)",SDDL_REVISION_1,&descriptor,nullptr))winrt::throw_last_error();SECURITY_ATTRIBUTES attributes{sizeof(attributes),descriptor,FALSE};NativeHandle unsafe(CreateMutexW(&attributes,FALSE,insecure.name().c_str()));LocalFree(descriptor);check(unsafe.get()!=nullptr,"The synthetic insecure mutex fixture must be created");rejects([&]{DesktopLease refused(insecure);},"An existing broad-access mutex must never become a trusted input lease");
        const auto insecure_mapping=DesktopLease::Scope::fixture("insecure-mapping-"+random_id());DesktopLease original_mapping(insecure_mapping);NativeHandle mapping(OpenFileMappingW(FILE_MAP_ALL_ACCESS,FALSE,(insecure_mapping.name()+L".State").c_str()));check(mapping.get()!=nullptr,"The isolated mapping security fixture must open");
        descriptor=nullptr;if(!ConvertStringSecurityDescriptorToSecurityDescriptorW(L"D:P(A;;GA;;;WD)",SDDL_REVISION_1,&descriptor,nullptr))winrt::throw_last_error();BOOL present{},defaulted{};PACL broad{};if(!GetSecurityDescriptorDacl(descriptor,&present,&broad,&defaulted)){LocalFree(descriptor);winrt::throw_last_error();}const auto changed_acl=SetSecurityInfo(mapping.get(),SE_KERNEL_OBJECT,DACL_SECURITY_INFORMATION|PROTECTED_DACL_SECURITY_INFORMATION,nullptr,nullptr,broad,nullptr);LocalFree(descriptor);check(changed_acl==ERROR_SUCCESS,"The synthetic mapping alone may be given its test-only unsafe ACL");rejects([&]{DesktopLease refused(insecure_mapping);},"An existing broad-access lease mapping must be rejected independently of the mutex ACL");
        auto mode=[&](const std::string& value,const std::string& key){std::ofstream(root/L"computer-use-fixture-mode.txt",std::ios::trunc)<<value;std::ofstream(root/L"computer-use-fixture-lease.txt",std::ios::trunc)<<key;};
        Object request;put(request,L"thread",a);put(request,L"operation","list_windows");request.SetNamedValue(L"arguments",Object{});const auto process_key="process-"+random_id();const auto process_scope=DesktopLease::Scope::fixture(process_key);DesktopLease waiting(process_scope);ProcessBackend backend(fixture,root,GetCurrentProcessId(),std::chrono::milliseconds(2000));
        mode("lease-hold",process_key);check(backend.request(request,[]{return false;}).GetNamedBoolean(L"lease_held"),"The dedicated helper must hold only its synthetic named input mutex");check(!waiting.try_acquire(b),"An active input gate in another process must exclude the parent controller");backend.stop();auto abandoned=waiting.try_acquire(b);check(abandoned.has_value()&&abandoned->abandoned(),"An owned helper's termination must permit explicit recovery of its abandoned input gate");abandoned.reset();waiting.release(b);
        mode("lease-idle",process_key);check(backend.request(request,[]{return false;}).GetNamedBoolean(L"lease_held")&&!waiting.try_acquire(b),"An idle logical thread lease must remain exclusive across live helper processes");backend.release_controls(a);auto after_release=waiting.try_acquire(b);check(after_release.has_value(),"The private release control message must free a live helper's matching logical lease");after_release.reset();waiting.release(b);backend.stop();
        mode("lease-idle",process_key);check(backend.request(request,[]{return false;}).GetNamedBoolean(L"lease_held"),"A second fixture helper must hold an idle logical lease");backend.stop();auto dead=waiting.try_acquire(b);check(dead.has_value()&&!dead->abandoned(),"A dead idle process owner must not retain its logical lease until expiry");dead.reset();waiting.release(b);
        mode("lease-short",process_key);check(backend.request(request,[]{return false;}).GetNamedBoolean(L"lease_held"),"The synthetic helper must accept a bounded short test-only lease");Sleep(80);auto expired=waiting.try_acquire(b);check(expired.has_value(),"A live but expired idle process lease must not block a new owner");expired.reset();backend.release_controls(a);check(waiting.owns(b),"A late release from an expired helper must not clear the replacement owner's lease");waiting.release(b);backend.stop();
        std::ofstream output(report);output<<"PASS: "<<checks<<" Computer Use shared desktop lease checks (synthetic kernel scope/helper; no desktop input)\n";return output?0:2;
    }catch(const winrt::hresult_error& error){std::ofstream(report)<<"FAIL after "<<checks<<" checks: "<<winrt::to_string(error.message())<<'\n';}catch(const std::exception& error){std::ofstream(report)<<"FAIL after "<<checks<<" checks: "<<error.what()<<'\n';}return 1;
}
} // namespace coincide
